/**
 ******************************************************************************
 * @file    test_battery_time.c
 * TEAM CODE (owner: Brendon - battery monitor and USB-C MSC) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29 Oct 2026 for his battery monitor subsystem (best-ui).
 * @brief   Unit tests for the fast time to empty / time to full estimator.
 *
 * Owner: Brendon Bone (best-ui).
 *
 * Coverage: no time before three readings, the instant current is used (not
 * the gauge's AverageCurrent), the 120-reading (2-minute) window, the
 * rounded average, every rule of battery_time.h (time to empty while
 * discharging and while draining on the charger, time to full while
 * charging, 0 when full while charging, 0 when the charger says the charge
 * is complete, both unknown without a capacity figure), the +/-10 mA
 * deadband on both sides, rounding of the minutes, the 99:59 cap, the
 * extremes without overflow, the held current (a 1 mA move does not move
 * the time), a time lasting until the average reaches 0 mA, an invalid
 * reading (no time, the average kept; a whole window of them restarts
 * it), the board scenarios (charging at +900 mA then unplugged: TO FULL
 * gone at once, TO EMPTY settled on the fifth publish and never 99:59;
 * plugging in; a charge finishing), the settling after a charger change (a
 * second change, an invalid reading, a change across an invalid reading, a
 * fresh start), a failed Current() read (AverageCurrent stands in and is
 * never averaged: after an unplug TO EMPTY is never 99:59, a full window
 * stays as it was), the shown times (steps of 1, 5 and 15 min, held until
 * one and a half steps away, one step at a time up and down, straight
 * there from two and a half steps and never two moves for one time, the
 * band edges, a steady countdown under an hour, 0 and unknown at once,
 * the cap, music that jumps every second, a small net current on the
 * charger with a wobble that is new every second or holds for 2-8 s),
 * and NULL safety.
 ******************************************************************************
 */
#include "unity.h"
#include "battery_time.h"

#include <string.h>

static BatTime_Estimator s_est;
static BatTime_Result    s_res;

void setUp(void)
{
    BatTime_Init(&s_est);
    memset(&s_res, 0xAA, sizeof(s_res));    /* every update must write all five fields */
}

void tearDown(void)
{
}

#define ASSERT_RESULT(avg, tte, ttf)                                  \
    do {                                                              \
        TEST_ASSERT_EQUAL_INT16((avg), s_res.avg_mA);                 \
        TEST_ASSERT_EQUAL_UINT16((tte), s_res.tte_min);               \
        TEST_ASSERT_EQUAL_UINT16((ttf), s_res.ttf_min);               \
    } while (0)

/* The times as the screens show them (in steps, held). */
#define ASSERT_SHOWN(tte, ttf)                                        \
    do {                                                              \
        TEST_ASSERT_EQUAL_UINT16((tte), s_res.tte_shown_min);         \
        TEST_ASSERT_EQUAL_UINT16((ttf), s_res.ttf_shown_min);         \
    } while (0)

/* A valid snapshot with the given instant current and capacities. The
 * gauge's AverageCurrent (current_mA) is set to +12345 mA, which no rule
 * may use: a test fails if the estimator ever reads it instead of the
 * instant current. */
static Battery_Snapshot_t snap_of(int16_t now_mA, uint16_t rm, uint16_t fcc)
{
    Battery_Snapshot_t s;

    memset(&s, 0, sizeof(s));
    s.valid             = 1U;
    s.voltage_mV        = 3300U;
    s.soc_pct           = 50U;
    s.current_mA        = 12345;
    s.current_now_mA    = now_mA;
    s.current_now_ok    = 1U;          /* a real Current() reading */
    s.remaining_mAh     = rm;
    s.full_capacity_mAh = fcc;
    s.tte_min           = BATMON_TIME_UNKNOWN;
    s.ttf_min           = BATMON_TIME_UNKNOWN;
    return s;
}

/* One publish with a valid reading. */
static void feed(int16_t now_mA, uint16_t rm, uint16_t fcc,
                 uint8_t charging, uint8_t complete)
{
    const Battery_Snapshot_t s = snap_of(now_mA, rm, fcc);

    BatTime_Update(&s_est, &s, charging, complete, &s_res);
}

/* n publishes with the same valid reading. */
static void feed_n(int n, int16_t now_mA, uint16_t rm, uint16_t fcc,
                   uint8_t charging, uint8_t complete)
{
    int k;

    for (k = 0; k < n; k++) {
        feed(now_mA, rm, fcc, charging, complete);
    }
}

/* One publish with an invalid reading (whatever its numbers say). */
static void feed_invalid(uint8_t charging)
{
    Battery_Snapshot_t s = snap_of(-500, 1000U, 3400U);

    s.valid = 0U;
    BatTime_Update(&s_est, &s, charging, 0U, &s_res);
}

/* One publish with a valid reading whose Current() read failed: as
 * battery_monitor.c builds it, AverageCurrent (avg_mA) in both currents
 * and current_now_ok 0. */
static void feed_stand_in(int16_t avg_mA, uint16_t rm, uint16_t fcc,
                          uint8_t charging, uint8_t complete)
{
    Battery_Snapshot_t s = snap_of(avg_mA, rm, fcc);

    s.current_mA     = avg_mA;
    s.current_now_ok = 0U;
    BatTime_Update(&s_est, &s, charging, complete, &s_res);
}

/* -------------------------------------------------------------------------- */
/* Start-up and inputs                                                         */
/* -------------------------------------------------------------------------- */

static void test_no_time_until_three_readings(void)
{
    /* Discharging at 120 mA with 3000 mAh left: 25:00 from the third
     * reading. The average itself is there from the first. */
    feed(-120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(-120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(-120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, 1500U, BATTIME_UNKNOWN);

    /* Charging at 900 mA with 400 mAh to go: 26.7 -> 27 min, also from the
     * third reading. */
    BatTime_Init(&s_est);
    feed(900, 3000U, 3400U, 1U, 0U);
    feed(900, 3000U, 3400U, 1U, 0U);
    ASSERT_RESULT(900, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(900, 3000U, 3400U, 1U, 0U);
    ASSERT_RESULT(900, BATTIME_UNKNOWN, 27U);
}

static void test_uses_instant_current_not_average_current(void)
{
    /* snap_of puts +12345 mA in AverageCurrent: used, this discharge would
     * look like charging and have no time to empty. */
    feed_n(3, -150, 1700U, 3400U, 0U, 0U);
    ASSERT_RESULT(-150, 680U, BATTIME_UNKNOWN);     /* 1700 * 60 / 150 */
}

static void test_null_safety(void)
{
    const Battery_Snapshot_t s = snap_of(-120, 3000U, 3400U);
    BatTime_Result r;

    BatTime_Init(NULL);                             /* must simply not crash */

    /* No estimator: the result says "no estimate". */
    memset(&r, 0xAA, sizeof(r));
    BatTime_Update(NULL, &s, 0U, 0U, &r);
    TEST_ASSERT_EQUAL_INT16(0, r.avg_mA);
    TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, r.tte_min);
    TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, r.ttf_min);

    TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, r.tte_shown_min);
    TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, r.ttf_shown_min);

    /* No result buffer: ignored, and the reading is not counted. */
    BatTime_Update(&s_est, &s, 0U, 0U, NULL);
    feed(-120, 3000U, 3400U, 0U, 0U);
    feed(-120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, BATTIME_UNKNOWN, BATTIME_UNKNOWN);   /* two readings so far */

    /* No snapshot: an invalid reading. */
    BatTime_Update(&s_est, NULL, 0U, 0U, &s_res);
    ASSERT_RESULT(0, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    ASSERT_SHOWN(BATTIME_UNKNOWN, BATTIME_UNKNOWN);
}

/* -------------------------------------------------------------------------- */
/* The average                                                                 */
/* -------------------------------------------------------------------------- */

static void test_average_is_the_last_120_readings(void)
{
    int k;

    /* Two minutes at the 1 Hz publish. -2, -4, ... -250 mA: up to 120
     * readings the mean of all of them (-(k + 1), exact); from the 121st
     * the oldest drops out (the mean of the last 120 is -(2k - 119)). */
    TEST_ASSERT_EQUAL_UINT(120U, BATTIME_WINDOW);
    for (k = 1; k <= 125; k++) {
        feed((int16_t)(-2 * k), 3000U, 3400U, 0U, 0U);
        if (k <= 120) {
            TEST_ASSERT_EQUAL_INT16(-(k + 1), s_res.avg_mA);        /* all of them */
        } else {
            TEST_ASSERT_EQUAL_INT16(-(2 * k - 119), s_res.avg_mA);  /* the last 120 */
        }
    }
}

static void test_average_rounds_to_the_nearest_ma(void)
{
    /* A half rounds away from zero, so both directions round alike. */
    feed(-100, 3000U, 3400U, 0U, 0U);
    feed(-101, 3000U, 3400U, 0U, 0U);
    TEST_ASSERT_EQUAL_INT16(-101, s_res.avg_mA);    /* -100.5 */
    feed(-100, 3000U, 3400U, 0U, 0U);
    TEST_ASSERT_EQUAL_INT16(-100, s_res.avg_mA);    /* -100.33 */

    BatTime_Init(&s_est);
    feed(100, 3000U, 3400U, 1U, 0U);
    feed(101, 3000U, 3400U, 1U, 0U);
    TEST_ASSERT_EQUAL_INT16(101, s_res.avg_mA);     /* 100.5 */
    feed(101, 3000U, 3400U, 1U, 0U);
    TEST_ASSERT_EQUAL_INT16(101, s_res.avg_mA);     /* 100.67 */
}

static void test_invalid_reading_keeps_the_average(void)
{
    feed_n(5, -500, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-500, 360U, BATTIME_UNKNOWN);     /* 3000 * 60 / 500 */

    /* The gauge misses a poll: no time for that publish. */
    feed_invalid(0U);
    ASSERT_RESULT(0, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    ASSERT_SHOWN(BATTIME_UNKNOWN, BATTIME_UNKNOWN);

    /* Back: the five -500 mA readings are still averaged, so a time is
     * there at once: (5 * -500 - 120) / 6 = -436.7 -> -437 mA, and
     * 3000 * 60 / 437 = 411.9 -> 412 min (shown 410: 5 min steps). */
    feed(-120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-437, 412U, BATTIME_UNKNOWN);
    ASSERT_SHOWN(410U, BATTIME_UNKNOWN);
}

/* -------------------------------------------------------------------------- */
/* The rules                                                                   */
/* -------------------------------------------------------------------------- */

static void test_time_to_empty_while_discharging(void)
{
    feed_n(3, -120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, 1500U, BATTIME_UNKNOWN);    /* 25:00, and no "to full" */

    /* RemainingCapacity drops: the time follows at once. */
    feed(-120, 2990U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, 1495U, BATTIME_UNKNOWN);

    /* Empty: 00:00. */
    BatTime_Init(&s_est);
    feed_n(3, -120, 0U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, 0U, BATTIME_UNKNOWN);
}

static void test_time_to_full_while_charging(void)
{
    /* 1700 mAh to go at 900 mA = 113.3 min; no "to empty": the battery is
     * not draining. */
    feed_n(3, 900, 1700U, 3400U, 1U, 0U);
    ASSERT_RESULT(900, BATTIME_UNKNOWN, 113U);
}

static void test_time_to_full_zero_when_full_while_charging(void)
{
    /* Topping off: RemainingCapacity has reached FullChargeCapacity while
     * the charger still trickles inside the deadband: 00:00, not --:--. */
    feed_n(3, 5, 3400U, 3400U, 1U, 0U);
    ASSERT_RESULT(5, BATTIME_UNKNOWN, 0U);

    /* RemainingCapacity above FullChargeCapacity (FCC lags the learning):
     * still 0, never a wrapped subtraction. */
    BatTime_Init(&s_est);
    feed_n(3, 900, 3410U, 3400U, 1U, 0U);
    ASSERT_RESULT(900, BATTIME_UNKNOWN, 0U);

    /* Full while the load takes more than the charger gives: still 0, and
     * the time to empty of the drain: 3400 * 60 / 50 = 4080 min. */
    BatTime_Init(&s_est);
    feed_n(3, -50, 3400U, 3400U, 1U, 0U);
    ASSERT_RESULT(-50, 4080U, 0U);
}

static void test_charging_deadband(void)
{
    /* 10 mAh to go. +9 mA is inside the deadband: no time. */
    feed_n(3, 9, 3390U, 3400U, 1U, 0U);
    ASSERT_RESULT(9, BATTIME_UNKNOWN, BATTIME_UNKNOWN);

    /* +10 mA is the edge: 10 * 60 / 10 = 60 min. */
    BatTime_Init(&s_est);
    feed_n(3, 10, 3390U, 3400U, 1U, 0U);
    ASSERT_RESULT(10, BATTIME_UNKNOWN, 60U);

    /* The edge applies to the rounded average: 9, 10, 10 = 9.67 -> 10, so
     * a time. The time comes from the held current, which took the first
     * average (9 mA) and does not move for 1 mA: 10 * 60 / 9 = 66.7 -> 67. */
    BatTime_Init(&s_est);
    feed(9, 3390U, 3400U, 1U, 0U);
    feed(10, 3390U, 3400U, 1U, 0U);
    feed(10, 3390U, 3400U, 1U, 0U);
    ASSERT_RESULT(10, BATTIME_UNKNOWN, 67U);

    /* Charging, but the load takes more than the charger gives (loud
     * music): no time to full, and the time to empty of the drain:
     * 1700 * 60 / 50 = 2040 min. */
    BatTime_Init(&s_est);
    feed_n(3, -50, 1700U, 3400U, 1U, 0U);
    ASSERT_RESULT(-50, 2040U, BATTIME_UNKNOWN);

    /* Charging, a drain inside the deadband: no time either way. */
    BatTime_Init(&s_est);
    feed_n(3, -9, 1700U, 3400U, 1U, 0U);
    ASSERT_RESULT(-9, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
}

static void test_a_time_lasts_until_the_current_reaches_zero(void)
{
    /* Draining starts at -10 mA: 50 mAh at 10 mA = 300 min. */
    feed_n(3, -10, 50U, 3400U, 0U, 0U);
    ASSERT_RESULT(-10, 300U, BATTIME_UNKNOWN);

    /* The average comes back to -4 mA: still draining (it only stops at
     * 0 mA), so still a time. It comes from the held current, which stays
     * at -10 mA: the average moved less than 10 mA. */
    feed_n((int)BATTIME_WINDOW, -4, 50U, 3400U, 0U, 0U);
    ASSERT_RESULT(-4, 300U, BATTIME_UNKNOWN);

    /* The average reaches 0 mA: no longer draining, no time. */
    feed_n((int)BATTIME_WINDOW, 0, 50U, 3400U, 0U, 0U);
    ASSERT_RESULT(0, BATTIME_UNKNOWN, BATTIME_UNKNOWN);

    /* -9 mA after that does not start it again: it starts at -10. */
    feed_n((int)BATTIME_WINDOW, -9, 50U, 3400U, 0U, 0U);
    ASSERT_RESULT(-9, BATTIME_UNKNOWN, BATTIME_UNKNOWN);

    /* Filling the same way round, on the charger: from +10 mA until 0. */
    BatTime_Init(&s_est);
    feed_n(3, 10, 3390U, 3400U, 1U, 0U);
    ASSERT_RESULT(10, BATTIME_UNKNOWN, 60U);
    feed_n((int)BATTIME_WINDOW, 4, 3390U, 3400U, 1U, 0U);
    ASSERT_RESULT(4, BATTIME_UNKNOWN, 60U);         /* held still +10 mA */
    feed_n((int)BATTIME_WINDOW, 0, 3390U, 3400U, 1U, 0U);
    ASSERT_RESULT(0, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
}

static void test_time_to_empty_while_draining_on_the_charger(void)
{
    /* What loud music can do on the charger (1 Nov 2026): the charger gives
     * about 400 mA near full, the speakers take more, so the battery drains
     * although the charger still says charging. Net -30 mA with 1500 mAh
     * left: 50:00 to empty, no time to full. */
    feed_n(5, 300, 1500U, 3400U, 1U, 0U);
    ASSERT_RESULT(300, BATTIME_UNKNOWN, 380U);      /* 1900 * 60 / 300 */
    feed_n(200, -30, 1500U, 3400U, 1U, 0U);         /* no charger change: no restart */
    TEST_ASSERT_EQUAL_INT16(-30, s_res.avg_mA);
    TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, s_res.ttf_min);
    /* The held current followed the average down in moves of 10 mA or
     * more, so it ended within 10 mA of it, and the time is worked out
     * from it: 1500 * 60 / |held|, rounded. */
    TEST_ASSERT_INT_WITHIN(5, -25, s_est.held_mA);  /* -30 .. -20 mA */
    TEST_ASSERT_EQUAL_UINT16((uint16_t)((90000 - s_est.held_mA / 2) / -s_est.held_mA),
                             s_res.tte_min);
    TEST_ASSERT_NOT_EQUAL(BATTIME_UNKNOWN, s_res.tte_shown_min);
    TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, s_res.ttf_shown_min);

    /* The music stops: charging again, the time to full comes back. The
     * held current ended within 5 % of +300 mA: 1900 * 60 / held. */
    feed_n(200, 300, 1500U, 3400U, 1U, 0U);
    TEST_ASSERT_EQUAL_INT16(300, s_res.avg_mA);
    TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, s_res.tte_min);
    TEST_ASSERT_INT_WITHIN(15, 300, s_est.held_mA);
    TEST_ASSERT_EQUAL_UINT16((uint16_t)((114000 + s_est.held_mA / 2) / s_est.held_mA),
                             s_res.ttf_min);
    TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, s_res.tte_shown_min);
    TEST_ASSERT_NOT_EQUAL(BATTIME_UNKNOWN, s_res.ttf_shown_min);
}

static void test_discharging_deadband(void)
{
    /* -9 mA is inside the deadband: no time. */
    feed_n(3, -9, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-9, BATTIME_UNKNOWN, BATTIME_UNKNOWN);

    /* -10 mA is the edge: 50 * 60 / 10 = 300 min. */
    BatTime_Init(&s_est);
    feed_n(3, -10, 50U, 3400U, 0U, 0U);
    ASSERT_RESULT(-10, 300U, BATTIME_UNKNOWN);

    /* No current at all. */
    BatTime_Init(&s_est);
    feed_n(3, 0, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(0, BATTIME_UNKNOWN, BATTIME_UNKNOWN);

    /* Not charging but current flowing in (e.g. a gauge offset): no time. */
    BatTime_Init(&s_est);
    feed_n(3, 200, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(200, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
}

static void test_time_to_full_zero_when_charge_complete(void)
{
    /* The charger says done (power good, STAT high) and the battery carries
     * the load: TO FULL 00:00 and TO EMPTY from the load. */
    feed_n(3, -120, 3400U, 3400U, 0U, 1U);
    ASSERT_RESULT(-120, 1700U, 0U);

    /* Done and no current to speak of: TO FULL only. */
    BatTime_Init(&s_est);
    feed_n(3, 0, 3400U, 3400U, 0U, 1U);
    ASSERT_RESULT(0, BATTIME_UNKNOWN, 0U);

    /* No charger input (not complete): no TO FULL, whatever RM says. */
    BatTime_Init(&s_est);
    feed_n(3, -120, 3400U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, 1700U, BATTIME_UNKNOWN);

    /* "Complete" only counts while not charging: charging rules first. */
    BatTime_Init(&s_est);
    feed_n(3, 900, 1700U, 3400U, 1U, 1U);
    ASSERT_RESULT(900, BATTIME_UNKNOWN, 113U);
}

static void test_no_capacity_figure_gives_no_time(void)
{
    /* FullChargeCapacity 0: the gauge has no figure yet. Not even the
     * charger's "complete" gives 00:00. */
    feed_n(3, -120, 0U, 0U, 0U, 1U);
    ASSERT_RESULT(-120, BATTIME_UNKNOWN, BATTIME_UNKNOWN);

    /* Charging: RM >= FCC would otherwise say full. */
    BatTime_Init(&s_est);
    feed_n(3, 900, 0U, 0U, 1U, 0U);
    ASSERT_RESULT(900, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
}

static void test_minutes_round_to_the_nearest(void)
{
    /* 1000 mAh at 70 mA = 857.1 min -> 857 */
    feed_n(3, -70, 1000U, 3400U, 0U, 0U);
    TEST_ASSERT_EQUAL_UINT16(857U, s_res.tte_min);

    /* 1000 mAh at 130 mA = 461.5 min -> 462 */
    BatTime_Init(&s_est);
    feed_n(3, -130, 1000U, 3400U, 0U, 0U);
    TEST_ASSERT_EQUAL_UINT16(462U, s_res.tte_min);

    /* 1001 mAh at 120 mA = 500.5 min: a half rounds up -> 501 */
    BatTime_Init(&s_est);
    feed_n(3, -120, 1001U, 3400U, 0U, 0U);
    TEST_ASSERT_EQUAL_UINT16(501U, s_res.tte_min);

    /* The same for TO FULL: 1001 mAh to go at 120 mA */
    BatTime_Init(&s_est);
    feed_n(3, 120, 2399U, 3400U, 1U, 0U);
    TEST_ASSERT_EQUAL_UINT16(501U, s_res.ttf_min);
}

static void test_times_capped_at_99_59(void)
{
    /* 5998 mAh at 60 mA = 5998 min: as it is. Shown in 15 min steps that
     * is 6000 (100:00), which the cap makes 5999 (99:59). */
    feed_n(3, -60, 5998U, 6500U, 0U, 0U);
    TEST_ASSERT_EQUAL_UINT16(5998U, s_res.tte_min);
    TEST_ASSERT_EQUAL_UINT16(5999U, s_res.tte_shown_min);

    /* 6000 mAh at 60 mA = 6000 min (100:00): capped at 5999 (99:59). */
    BatTime_Init(&s_est);
    feed_n(3, -60, 6000U, 6500U, 0U, 0U);
    TEST_ASSERT_EQUAL_UINT16(BATTIME_MAX_MIN, s_res.tte_min);
    TEST_ASSERT_EQUAL_UINT16(5999U, BATTIME_MAX_MIN);
    TEST_ASSERT_EQUAL_UINT16(5999U, s_res.tte_shown_min);

    /* TO FULL the same: 6000 mAh to go at 60 mA. */
    BatTime_Init(&s_est);
    feed_n(3, 60, 0U, 6000U, 1U, 0U);
    TEST_ASSERT_EQUAL_UINT16(5999U, s_res.ttf_min);
    TEST_ASSERT_EQUAL_UINT16(5999U, s_res.ttf_shown_min);
}

static void test_extremes_do_not_overflow(void)
{
    /* The largest capacity at the smallest current that gives a time:
     * 65535 * 60 / 10 = 393 210 min -> capped (16-bit sums would wrap). */
    feed_n(3, -10, 65535U, 65535U, 0U, 0U);
    ASSERT_RESULT(-10, 5999U, BATTIME_UNKNOWN);
    BatTime_Init(&s_est);
    feed_n(3, 10, 0U, 65535U, 1U, 0U);
    ASSERT_RESULT(10, BATTIME_UNKNOWN, 5999U);

    /* A full window of the largest currents: 65535 mAh at 32768 mA and at
     * 32767 mA are both 120 min (the sum, 120 * -32768, fits 32 bits). */
    BatTime_Init(&s_est);
    feed_n((int)BATTIME_WINDOW, -32768, 65535U, 65535U, 0U, 0U);
    ASSERT_RESULT(-32768, 120U, BATTIME_UNKNOWN);
    BatTime_Init(&s_est);
    feed_n((int)BATTIME_WINDOW, 32767, 0U, 65535U, 1U, 0U);
    ASSERT_RESULT(32767, BATTIME_UNKNOWN, 120U);
}

/* -------------------------------------------------------------------------- */
/* Charger plugged in or out: restart and settle                               */
/* -------------------------------------------------------------------------- */

static void test_unplug_after_charging_gives_to_empty_in_seconds(void)
{
    /* What the board showed: charging at +900 mA, then the charger
     * unplugged; the gauge's own estimate took minutes to go from "to full"
     * through 99 h to "to empty". Here the first reading after the unplug
     * is still the charging second (+900), the next one half and half
     * (+390), then the real load of about -120 mA. The average shown is the
     * reading itself while nothing is averaged, then the load only. */
    static const int16_t now[8] = {900, 390, -110, -130, -120, -120, -120, -120};
    static const int16_t avg[8] = {900, 390, -110, -120, -120, -120, -120, -120};
    int k;

    feed_n(12, 900, 3000U, 3400U, 1U, 0U);
    ASSERT_RESULT(900, BATTIME_UNKNOWN, 27U);       /* 400 mAh at 900 mA */

    for (k = 0; k < 8; k++) {
        feed(now[k], 3000U, 3400U, 0U, 0U);
        /* TO FULL is gone from the first publish without the charger:
         * never a "to full 99 h" phase. */
        TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, s_res.ttf_min);
        /* The two mixed readings are shown but never averaged. */
        TEST_ASSERT_EQUAL_INT16(avg[k], s_res.avg_mA);
        if (k < 4) {
            /* two left out, then three averaged: --:--, never 99:59 */
            TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, s_res.tte_min);
            TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, s_res.tte_shown_min);
        } else {
            /* from the fifth publish: the settled 25:00 straight away */
            TEST_ASSERT_EQUAL_UINT16(1500U, s_res.tte_min);
            TEST_ASSERT_EQUAL_UINT16(1500U, s_res.tte_shown_min);
        }
        TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, s_res.ttf_shown_min);   /* shown gone at once too */
    }
}

static void test_plug_in_gives_to_full_in_seconds(void)
{
    /* The other way round: discharging at -120 mA, then plugged in. The
     * first reading is still the discharge, the next one mixed. */
    static const int16_t now[8] = {-120, 400, 900, 900, 900, 900, 900, 900};
    int k;

    feed_n(12, -120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, 1500U, BATTIME_UNKNOWN);

    for (k = 0; k < 8; k++) {
        feed(now[k], 3000U, 3400U, 1U, 0U);
        TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, s_res.tte_min);   /* gone at once */
        TEST_ASSERT_EQUAL_UINT16((k < 4) ? BATTIME_UNKNOWN : 27U, s_res.ttf_min);
    }
    TEST_ASSERT_EQUAL_INT16(900, s_res.avg_mA);
}

static void test_charge_finishing_restarts_too(void)
{
    /* Topping off at +150 mA with 10 mAh to go: 4 min. */
    feed_n(5, 150, 3390U, 3400U, 1U, 0U);
    ASSERT_RESULT(150, BATTIME_UNKNOWN, 4U);

    /* STAT goes high (complete) and the battery carries the -120 mA load:
     * the charging flag changed, so the same restart and settling apply. */
    feed(150, 3400U, 3400U, 0U, 1U);
    ASSERT_RESULT(150, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(-60, 3400U, 3400U, 0U, 1U);
    feed(-120, 3400U, 3400U, 0U, 1U);
    feed(-120, 3400U, 3400U, 0U, 1U);
    ASSERT_RESULT(-120, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(-120, 3400U, 3400U, 0U, 1U);
    ASSERT_RESULT(-120, 1700U, 0U);

    /* Unplugged later (no input): the charging flag stays 0, so no restart.
     * TO EMPTY carries on (3399 * 60 / 120 = 1699.5 -> 1700), TO FULL goes. */
    feed(-120, 3399U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, 1700U, BATTIME_UNKNOWN);
}

static void test_change_during_settling_starts_it_again(void)
{
    feed_n(5, -120, 3000U, 3400U, 0U, 0U);

    feed(-120, 3000U, 3400U, 1U, 0U);   /* plugged in: left out */
    feed(400, 3000U, 3400U, 0U, 0U);    /* out again (a loose plug): restart, left out */
    feed(-120, 3000U, 3400U, 0U, 0U);   /* left out */
    feed(-120, 3000U, 3400U, 0U, 0U);   /* averaged: 1 */
    feed(-120, 3000U, 3400U, 0U, 0U);   /* averaged: 2 */
    ASSERT_RESULT(-120, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(-120, 3000U, 3400U, 0U, 0U);   /* averaged: 3 */
    ASSERT_RESULT(-120, 1500U, BATTIME_UNKNOWN);
}

static void test_invalid_reading_counts_toward_settling(void)
{
    feed_n(5, 900, 3000U, 3400U, 1U, 0U);

    /* Unplugged, and the gauge misses the next poll: the miss still counts
     * as one of the two publishes left out (they stand for time). */
    feed(900, 3000U, 3400U, 0U, 0U);    /* left out */
    feed_invalid(0U);                   /* left out */
    ASSERT_RESULT(0, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(-120, 3000U, 3400U, 0U, 0U);   /* averaged: 1 */
    feed(-120, 3000U, 3400U, 0U, 0U);   /* averaged: 2 */
    ASSERT_RESULT(-120, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(-120, 3000U, 3400U, 0U, 0U);   /* averaged: 3: the fifth publish, as without the miss */
    ASSERT_RESULT(-120, 1500U, BATTIME_UNKNOWN);
}

static void test_change_across_invalid_reading_still_settles(void)
{
    feed_n(5, 900, 3000U, 3400U, 1U, 0U);

    /* The gauge misses a poll while charging; the next valid reading is the
     * first without the charger. It is compared with the last VALID one, so
     * the change is still seen: restart and settle. */
    feed_invalid(1U);
    feed(900, 3000U, 3400U, 0U, 0U);    /* left out */
    ASSERT_RESULT(900, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(390, 3000U, 3400U, 0U, 0U);    /* left out */
    feed(-120, 3000U, 3400U, 0U, 0U);
    feed(-120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(-120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, 1500U, BATTIME_UNKNOWN);
}

static void test_first_reading_after_init_only_records_the_flag(void)
{
    feed_n(5, 900, 3000U, 3400U, 1U, 0U);

    /* A fresh start: the first reading has nothing to compare with, so it is
     * averaged at once although the flag differs from before the restart. */
    BatTime_Init(&s_est);
    feed(-120, 3000U, 3400U, 0U, 0U);
    feed(-120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(-120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, 1500U, BATTIME_UNKNOWN);
}

/* -------------------------------------------------------------------------- */
/* A failed Current() read: AverageCurrent stands in, never averaged           */
/* -------------------------------------------------------------------------- */

static void test_failed_instant_read_after_unplug_is_left_out(void)
{
    /* The unplug of the board scenario above, but on the third publish the
     * gauge NACKs Current(). AverageCurrent stands in, still +600 mA from
     * the charging (it takes minutes to swing through zero). Averaged with
     * the -120 mA load it would hold TO EMPTY at --:-- for 8 s, then show
     * 99:59 and creep down. Left out, TO EMPTY waits one publish longer and
     * is then the clean 25:00 at once; the stand-in is only shown as the
     * average while nothing is averaged. */
    static const int16_t now[9] = {900, 390, 600, -120, -120, -120, -120, -120, -120};
    int k;

    feed_n(12, 900, 3000U, 3400U, 1U, 0U);
    for (k = 0; k < 9; k++) {
        if (k == 2) {
            feed_stand_in(now[k], 3000U, 3400U, 0U, 0U);
        } else {
            feed(now[k], 3000U, 3400U, 0U, 0U);
        }
        TEST_ASSERT_EQUAL_INT16(now[k], s_res.avg_mA);
        TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, s_res.ttf_min);
        TEST_ASSERT_EQUAL_UINT16((k < 5) ? BATTIME_UNKNOWN : 1500U, s_res.tte_min);
    }

    /* A stand-in among the two readings left out after the change changes
     * nothing: they stand for time. TO EMPTY on the fifth publish, as
     * without it. */
    BatTime_Init(&s_est);
    feed_n(12, 900, 3000U, 3400U, 1U, 0U);
    feed(900, 3000U, 3400U, 0U, 0U);
    feed_stand_in(600, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(600, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed_n(2, -120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(-120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, 1500U, BATTIME_UNKNOWN);
}

static void test_failed_instant_read_keeps_the_window(void)
{
    int k;

    /* A full window, -100 mA sixty times then -140 mA sixty times (-120):
     * a +700 mA stand-in neither enters it nor pushes the oldest reading
     * out. Averaged, it would give -113 mA and TO EMPTY 26:33 for 2 min. */
    for (k = 0; k < (int)BATTIME_WINDOW; k++) {
        feed((k < 60) ? -100 : -140, 3000U, 3400U, 0U, 0U);
    }
    ASSERT_RESULT(-120, 1500U, BATTIME_UNKNOWN);
    feed_stand_in(700, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, 1500U, BATTIME_UNKNOWN);
    /* The next real reading replaces the oldest -100 as usual:
     * (-14400 + 100 - 220) / 120 = -121 mA. The held current (-120 mA)
     * does not move for 1 mA, so the time stays 25:00. */
    feed(-220, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-121, 1500U, BATTIME_UNKNOWN);

    /* Fewer than three readings averaged: their mean, and still no time
     * until a third real one. */
    BatTime_Init(&s_est);
    feed(-110, 3000U, 3400U, 0U, 0U);
    feed(-130, 3000U, 3400U, 0U, 0U);
    feed_stand_in(600, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(-120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, 1500U, BATTIME_UNKNOWN);

    /* Nothing averaged yet (a fresh start): the stand-in is only shown. */
    BatTime_Init(&s_est);
    feed_stand_in(-150, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-150, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed_n(2, -120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(-120, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-120, 1500U, BATTIME_UNKNOWN);

    /* Charging the same way round: TO FULL keeps the clean 27 min. */
    BatTime_Init(&s_est);
    feed_n(10, 900, 3000U, 3400U, 1U, 0U);
    feed_stand_in(-200, 3000U, 3400U, 1U, 0U);
    ASSERT_RESULT(900, BATTIME_UNKNOWN, 27U);
}

/* -------------------------------------------------------------------------- */
/* The shown times: in steps, held                                             */
/* -------------------------------------------------------------------------- */

/* At -60 mA every mAh left is one minute: the time in minutes is the
 * RemainingCapacity, which makes these tests easy to read. */
static void feed_minutes(uint16_t minutes)
{
    feed(-60, minutes, 6500U, 0U, 0U);
}

static void test_shown_time_moves_in_steps(void)
{
    /* From 10 h: 15 min steps, held within 22.5 min. */
    feed_n(3, -60, 1500U, 6500U, 0U, 0U);
    ASSERT_SHOWN(1500U, BATTIME_UNKNOWN);          /* 25:00 */
    feed_minutes(1495U);
    TEST_ASSERT_EQUAL_UINT16(1495U, s_res.tte_min);
    ASSERT_SHOWN(1500U, BATTIME_UNKNOWN);          /* 5 min away: held */
    feed_minutes(1478U);
    ASSERT_SHOWN(1500U, BATTIME_UNKNOWN);          /* 22 min away: held */
    feed_minutes(1477U);
    ASSERT_SHOWN(1485U, BATTIME_UNKNOWN);          /* 23 min away: ONE step down */
    feed_minutes(1477U);
    ASSERT_SHOWN(1485U, BATTIME_UNKNOWN);          /* 8 min away now: held */
    feed_minutes(1508U);
    ASSERT_SHOWN(1500U, BATTIME_UNKNOWN);          /* 23 min UP: one step up */
    feed_minutes(1000U);
    ASSERT_SHOWN(1005U, BATTIME_UNKNOWN);          /* 500 min away: straight there (rounded) */

    /* Two and a half steps (37.5 min) is the edge: 37 min away is one
     * step, 38 min away is straight there. */
    BatTime_Init(&s_est);
    feed_n(3, -60, 1500U, 6500U, 0U, 0U);
    feed_minutes(1463U);
    ASSERT_SHOWN(1485U, BATTIME_UNKNOWN);          /* 37 min: one step */
    BatTime_Init(&s_est);
    feed_n(3, -60, 1500U, 6500U, 0U, 0U);
    feed_minutes(1462U);
    ASSERT_SHOWN(1455U, BATTIME_UNKNOWN);          /* 38 min: straight there */

    /* Straight there, then held: never two single steps one second
     * apart for the same time (40 min away, 2.67 steps). */
    BatTime_Init(&s_est);
    feed_n(3, -60, 1500U, 6500U, 0U, 0U);
    feed_minutes(1460U);
    ASSERT_SHOWN(1455U, BATTIME_UNKNOWN);
    feed_minutes(1460U);
    ASSERT_SHOWN(1455U, BATTIME_UNKNOWN);

    /* Under 10 h: 5 min steps, held within 7.5 min. */
    BatTime_Init(&s_est);
    feed_n(3, -60, 500U, 6500U, 0U, 0U);
    ASSERT_SHOWN(500U, BATTIME_UNKNOWN);
    feed_minutes(493U);
    ASSERT_SHOWN(500U, BATTIME_UNKNOWN);           /* 7 min away: held */
    feed_minutes(492U);
    ASSERT_SHOWN(495U, BATTIME_UNKNOWN);           /* 8 min away: one step down */
    feed_minutes(503U);
    ASSERT_SHOWN(500U, BATTIME_UNKNOWN);           /* 8 min up: one step up */

    /* Under 1 h: 1 min steps, held within 1.5 min: a steady countdown
     * shows every minute, one behind. */
    BatTime_Init(&s_est);
    feed_n(3, -60, 50U, 6500U, 0U, 0U);
    ASSERT_SHOWN(50U, BATTIME_UNKNOWN);
    feed_minutes(49U);
    ASSERT_SHOWN(50U, BATTIME_UNKNOWN);            /* 1 min away: held */
    feed_minutes(48U);
    ASSERT_SHOWN(49U, BATTIME_UNKNOWN);            /* 2 min away: one step */
    feed_minutes(47U);
    ASSERT_SHOWN(48U, BATTIME_UNKNOWN);
    feed_minutes(50U);
    ASSERT_SHOWN(49U, BATTIME_UNKNOWN);            /* 2 min up: one step up */
    feed_minutes(46U);
    ASSERT_SHOWN(46U, BATTIME_UNKNOWN);            /* 3 min: two and a half steps or more, straight there */
}

static void test_steady_countdown_under_an_hour(void)
{
    /* A steady drain going under an hour: 01:10, then 01:05 once the time
     * is 1.5 five-minute steps below, then straight to the minute (00:59)
     * when the time enters the 1 min band, then one minute at a time. */
    static const uint16_t time[8]  = {70U, 62U, 61U, 60U, 59U, 58U, 57U, 56U};
    static const uint16_t shown[8] = {70U, 65U, 65U, 65U, 59U, 59U, 58U, 57U};
    int k;

    feed_n(2, -60, 70U, 6500U, 0U, 0U);
    for (k = 0; k < 8; k++) {
        feed_minutes(time[k]);
        ASSERT_SHOWN(shown[k], BATTIME_UNKNOWN);
    }
}

static void test_shown_time_at_the_band_edges(void)
{
    /* 59 min is in the 1 min band, 60 in the 5 min band: the step of the
     * NEW time decides. From 59, 60 is 1 min away: held (it would need
     * 7.5 min in the 5 min band); 67 is 8 min away: one 5 min step, 64,
     * rounded to the 5 min grid: 65. */
    feed_n(3, -60, 59U, 6500U, 0U, 0U);
    ASSERT_SHOWN(59U, BATTIME_UNKNOWN);
    feed_minutes(60U);
    ASSERT_SHOWN(59U, BATTIME_UNKNOWN);
    feed_minutes(67U);
    ASSERT_SHOWN(65U, BATTIME_UNKNOWN);

    /* From 60 (5 min grid) down to 58 (1 min band): 2 min away, so one
     * 1 min step: 59. */
    BatTime_Init(&s_est);
    feed_n(3, -60, 60U, 6500U, 0U, 0U);
    ASSERT_SHOWN(60U, BATTIME_UNKNOWN);
    feed_minutes(58U);
    ASSERT_SHOWN(59U, BATTIME_UNKNOWN);

    /* 10:00 (15 min grid) down into the 5 min band: 595 is 5 min away,
     * held; 592 is 8 min away: one 5 min step, 595. */
    BatTime_Init(&s_est);
    feed_n(3, -60, 600U, 6500U, 0U, 0U);
    ASSERT_SHOWN(600U, BATTIME_UNKNOWN);
    feed_minutes(595U);
    ASSERT_SHOWN(600U, BATTIME_UNKNOWN);
    feed_minutes(592U);
    ASSERT_SHOWN(595U, BATTIME_UNKNOWN);

    /* A first time is rounded to its own step: 62 -> 60 (5 min grid),
     * 608 -> 615 (15 min grid: 600, 615). */
    BatTime_Init(&s_est);
    feed_n(3, -60, 62U, 6500U, 0U, 0U);
    ASSERT_SHOWN(60U, BATTIME_UNKNOWN);
    BatTime_Init(&s_est);
    feed_n(3, -60, 608U, 6500U, 0U, 0U);
    ASSERT_SHOWN(615U, BATTIME_UNKNOWN);
}

static void test_shown_time_zero_and_unknown_at_once(void)
{
    /* Charging at +100 mA with 10 mAh to go: 6 min. */
    feed_n(3, 100, 3390U, 3400U, 1U, 0U);
    ASSERT_SHOWN(BATTIME_UNKNOWN, 6U);
    feed(100, 3399U, 3400U, 1U, 0U);                /* 0.6 -> 1 min: 5 min away */
    ASSERT_SHOWN(BATTIME_UNKNOWN, 1U);
    feed(100, 3400U, 3400U, 1U, 0U);                /* full: 0 at once, though only 1 min away */
    ASSERT_SHOWN(BATTIME_UNKNOWN, 0U);
    feed_invalid(1U);                               /* a missed poll: --:-- at once */
    ASSERT_SHOWN(BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed(100, 3400U, 3400U, 1U, 0U);                /* back: shown at once */
    ASSERT_SHOWN(BATTIME_UNKNOWN, 0U);
}

/* A repeatable "song": every second a current between -135 and -220 mA
 * from a simple pseudo-random sequence (a linear congruential generator:
 * the same numbers on every run). */
static int16_t music_mA(uint32_t *seed)
{
    *seed = *seed * 1103515245U + 12345U;
    return (int16_t)(-135 - (int16_t)((*seed >> 16) % 86U));
}

static void test_music_does_not_make_the_shown_time_jump(void)
{
    uint32_t seed = 1U;
    int16_t  avg_was;
    uint16_t shown_was;
    int      avg_changes = 0, shown_changes = 0, k;

    /* What the board showed (1 Nov 2026): about -125 mA idle, and music
     * that jumps between about -135 and -220 mA from one second to the
     * next. Two minutes idle with 3000 mAh: 24:00. */
    feed_n(120, -125, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-125, 1440U, BATTIME_UNKNOWN);
    ASSERT_SHOWN(1440U, BATTIME_UNKNOWN);

    /* Two minutes of music: the average moves to the music's and the
     * shown time comes down with it, in 15 min steps, to about 17 h. */
    for (k = 0; k < 120; k++) {
        feed(music_mA(&seed), 3000U, 3400U, 0U, 0U);
    }
    TEST_ASSERT_UINT16_WITHIN(60U, 1020U, s_res.tte_shown_min);

    /* Ten more minutes of it: the 2-minute average still moves (by a mA
     * here and there, many times), the shown time hardly at all. */
    avg_was   = s_res.avg_mA;
    shown_was = s_res.tte_shown_min;
    for (k = 0; k < 600; k++) {
        feed(music_mA(&seed), 3000U, 3400U, 0U, 0U);
        avg_changes   += (s_res.avg_mA != avg_was) ? 1 : 0;
        shown_changes += (s_res.tte_shown_min != shown_was) ? 1 : 0;
        avg_was   = s_res.avg_mA;
        shown_was = s_res.tte_shown_min;
    }
    TEST_ASSERT_GREATER_THAN_INT(50, avg_changes);
    TEST_ASSERT_LESS_OR_EQUAL_INT(2, shown_changes);
}

/* Charging with loud music: about a +/-50 mA wobble on a small net
 * current, from the same kind of repeatable sequence. */
static int16_t net_mA(uint32_t *seed, int16_t base)
{
    *seed = *seed * 1103515245U + 12345U;
    return (int16_t)(base - 50 + (int16_t)((*seed >> 16) % 101U));
}

static void test_small_net_current_on_the_charger(void)
{
    uint32_t seed = 7U;
    uint16_t was;
    int      changes, k;

    /* On the charger the battery may only lose 30 mA (loud music taking
     * almost all the charger gives). 1 mA is then a large part of the
     * time: 2000 mAh lasts 66.7 h at 30 mA but 60.6 h at 33 mA. Without
     * the held current the shown time changed every 3-4 s; now it changes
     * rarely, and "Time left" never turns into "To full --:--" (the time
     * to empty stays known). Here the wobble is new every second. */
    for (k = 0; k < 300; k++) {
        feed(net_mA(&seed, -30), 2000U, 2600U, 1U, 0U);
    }
    was     = s_res.tte_shown_min;
    changes = 0;
    for (k = 0; k < 1200; k++) {                    /* 20 minutes */
        feed(net_mA(&seed, -30), 2000U, 2600U, 1U, 0U);
        TEST_ASSERT_NOT_EQUAL(BATTIME_UNKNOWN, s_res.tte_shown_min);
        TEST_ASSERT_EQUAL_UINT16(BATTIME_UNKNOWN, s_res.ttf_shown_min);
        changes += (s_res.tte_shown_min != was) ? 1 : 0;
        was = s_res.tte_shown_min;
    }
    TEST_ASSERT_LESS_OR_EQUAL_INT(30, changes);

    /* The same with +50 mA going in: TO FULL. */
    BatTime_Init(&s_est);
    for (k = 0; k < 300; k++) {
        feed(net_mA(&seed, 50), 2000U, 2600U, 1U, 0U);
    }
    was     = s_res.ttf_shown_min;
    changes = 0;
    for (k = 0; k < 1200; k++) {
        feed(net_mA(&seed, 50), 2000U, 2600U, 1U, 0U);
        TEST_ASSERT_NOT_EQUAL(BATTIME_UNKNOWN, s_res.ttf_shown_min);
        changes += (s_res.ttf_shown_min != was) ? 1 : 0;
        was = s_res.ttf_shown_min;
    }
    TEST_ASSERT_LESS_OR_EQUAL_INT(30, changes);
}

/* Music whose loudness holds for 2 to 8 s at a time, as real music does:
 * a new level within base +/-50 mA, held for 2..8 readings. */
static int16_t slow_music_mA(uint32_t *seed, int16_t base, int *hold, int16_t *level)
{
    if (*hold <= 0) {
        *seed  = *seed * 1103515245U + 12345U;
        *level = (int16_t)(base - 50 + (int16_t)((*seed >> 16) % 101U));
        *seed  = *seed * 1103515245U + 12345U;
        *hold  = 2 + (int)((*seed >> 16) % 7U);
    }
    (*hold)--;
    return *level;
}

static void test_slow_music_on_the_charger(void)
{
    uint32_t seed = 2U;
    int      hold = 0, changes = 0, k;
    int16_t  level = 0;
    uint16_t was;

    /* When the loudness holds for a few seconds the 2-minute average
     * wobbles by 4-12 mA instead of 2-3 mA. With a 3 mA hold that made a
     * time of about 60 h on the charger change every 20 s by 5-12 h; with
     * the 10 mA hold it changes only a few times in 20 minutes. */
    for (k = 0; k < 300; k++) {
        feed(slow_music_mA(&seed, -30, &hold, &level), 1950U, 2600U, 1U, 0U);
    }
    was = s_res.tte_shown_min;
    for (k = 0; k < 1200; k++) {
        feed(slow_music_mA(&seed, -30, &hold, &level), 1950U, 2600U, 1U, 0U);
        changes += (s_res.tte_shown_min != was) ? 1 : 0;
        was = s_res.tte_shown_min;
    }
    TEST_ASSERT_LESS_OR_EQUAL_INT(10, changes);
}

static void test_gauge_out_for_two_minutes_restarts_the_average(void)
{
    int k;

    /* Loud music, then the gauge stops answering for 119 polls (just under
     * two minutes): the readings are kept. The music stopped meanwhile:
     * the first new reading is averaged with them: (5 * -350 - 125) / 6. */
    feed_n(5, -350, 3000U, 3400U, 0U, 0U);
    for (k = 0; k < 119; k++) {
        feed_invalid(0U);
    }
    feed(-125, 3000U, 3400U, 0U, 0U);
    TEST_ASSERT_EQUAL_INT16(-313, s_res.avg_mA);    /* -312.5, a half away from zero */
    TEST_ASSERT_NOT_EQUAL(BATTIME_UNKNOWN, s_res.tte_min);

    /* Out for 120 polls (a whole window): the old readings say nothing
     * about now, so the average starts again: only the new reading, and
     * no time until three readings. */
    BatTime_Init(&s_est);
    feed_n(5, -350, 3000U, 3400U, 0U, 0U);
    for (k = 0; k < (int)BATTIME_WINDOW; k++) {
        feed_invalid(0U);
    }
    feed(-125, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-125, BATTIME_UNKNOWN, BATTIME_UNKNOWN);
    feed_n(2, -125, 3000U, 3400U, 0U, 0U);
    ASSERT_RESULT(-125, 1440U, BATTIME_UNKNOWN);
}

